"""Synthetic Russian CRM: architecture and all app files generated by Qwen."""
import ast,hashlib,json,os,pathlib,subprocess,sys,time,urllib.request
REPO="DSLitvinov1/my_first_repo"
DIR=pathlib.Path("/tmp")/("crm_generated_"+os.environ.get("GITHUB_RUN_ID","local"))
TRUSTED=pathlib.Path(__file__).resolve().parent
NAMES=("storage.py","crm.py","main.py")
ARCHITECT="qwen3:4b"; WRITER="qwen2.5-coder:3b"; REVIEWER="qwen3:4b"
ALLOWED_IMPORTS={"json","pathlib","argparse","sys","typing","datetime","collections","crm","storage"}
CALLS=0
def ask(model,prompt,structured=False):
    global CALLS
    CALLS+=1
    if CALLS>14:raise RuntimeError("Model-call safety limit reached")
    body={"model":model,"prompt":prompt,"stream":False,"think":False,"keep_alive":"0",
          "options":{"num_ctx":4096,"num_predict":1700,"num_thread":4,"num_gpu":0,"temperature":0}}
    if structured:body["format"]="json"
    request=urllib.request.Request("http://127.0.0.1:11434/api/generate",
                 data=json.dumps(body).encode(),method="POST",
                 headers={"Content-Type":"application/json"})
    opener=urllib.request.build_opener(urllib.request.ProxyHandler({}))
    with opener.open(request,timeout=240) as response:r=json.load(response)
    if not r.get("done"):raise ValueError("Incomplete model response")
    return str(r.get("response","")).strip()
def source(answer):
    x=answer.strip()
    fence=chr(96)*3
    if x.startswith(fence):
        lines=x.splitlines()
        x="\n".join(lines[1:-1] if lines[-1].strip()==fence else lines[1:])
    if not (20<len(x)<20000):raise ValueError("Invalid size")
    ast.parse(x)
    return x+"\n"
def guard(txt):
    tree=ast.parse(txt)
    for n in ast.walk(tree):
        if isinstance(n,(ast.Import,ast.ImportFrom)):
            mods=[x.name.split(".")[0] for x in n.names] if isinstance(n,ast.Import) else [(n.module or "").split(".")[0]]
            if any(m not in ALLOWED_IMPORTS for m in mods):raise ValueError("Unsafe import")
        if isinstance(n,ast.Call) and isinstance(n.func,ast.Name) and n.func.id in {"eval","exec","compile","__import__","breakpoint"}:
            raise ValueError("Dynamic execution disallowed")
        if isinstance(n,ast.Attribute) and n.attr in {"system","popen","spawn","unlink","rmtree"}:
            raise ValueError("Unsafe file/process operation")
    return True
def required_contract(name,txt):
    tree=ast.parse(txt)
    if name=="storage.py":
        functions={n.name for n in tree.body if isinstance(n,(ast.FunctionDef,ast.AsyncFunctionDef))}
        missing={"load_records","save_records"}-functions
        if missing:raise ValueError("storage.py requires top-level load_records(path), save_records(path,records): "+",".join(sorted(missing)))
    elif name=="crm.py":
        classes=[n for n in tree.body if isinstance(n,ast.ClassDef) and n.name=="CRM"]
        if len(classes)!=1:raise ValueError("crm.py requires top-level class CRM")
        methods={n.name for n in classes[0].body if isinstance(n,(ast.FunctionDef,ast.AsyncFunctionDef))}
        missing={"__init__","add","all","search","edit","set_status"}-methods
        if missing:raise ValueError("CRM requires public methods: "+",".join(sorted(missing)))
        if not any(isinstance(n,ast.Import) and any(a.name=="storage" for a in n.names) or isinstance(n,ast.ImportFrom) and n.module=="storage" for n in tree.body):
            raise ValueError("CRM must import the generated storage module for persistence")
    elif name=="main.py":
        imports=[n for n in tree.body if isinstance(n,(ast.Import,ast.ImportFrom))]
        if not any(isinstance(n,ast.Import) and any(a.name=="crm" for a in n.names) or isinstance(n,ast.ImportFrom) and n.module=="crm" for n in imports):
            raise ValueError("main.py must import generated crm.py")
        if "argparse" not in txt:raise ValueError("main.py must provide argparse CLI with --db")
    return True
def store(name,txt):
    if name not in NAMES or DIR.is_symlink():raise ValueError("Output path denied")
    DIR.mkdir(mode=0o755,parents=True,exist_ok=True)
    p=DIR/name
    if p.is_symlink() or p.resolve().parent!=DIR.resolve():raise ValueError("Output escape")
    guard(txt)
    required_contract(name,txt)
    p.write_text(txt,encoding="utf-8")
def tests():
    env={"PATH":os.environ.get("PATH",""),"HOME":"/tmp","LANG":"C.UTF-8",
         "PYTHONIOENCODING":"utf-8","CRM_TARGET":str(DIR)}
    exe=[sys.executable,"-S",str(TRUSTED/"acceptance_check.py")]
    if os.geteuid()==0:
        DIR.chmod(0o755)
        exe=["runuser","-u","nobody","--"]+exe
    r=subprocess.run(exe,cwd="/tmp",env=env,text=True,stdout=subprocess.PIPE,
                     stderr=subprocess.STDOUT,timeout=100)
    return r.returncode==0,r.stdout[-6500:]
def run():
    if os.environ.get("GITHUB_REPOSITORY")!=REPO or os.environ.get("CRM_PUBLIC_FREE_CONFIRMED")!="yes":
        raise ValueError("Free public repository confirmation required")
    if os.environ.get("GITHUB_TOKEN"):raise ValueError("Never expose GitHub token to writer")
    started=time.monotonic()
    spec=(TRUSTED/"requirements_ru.txt").read_text(encoding="utf-8")
    planning=("Ты архитектор. По русскому ТЗ спланируй структуру новой Python CRM. "
              "Верни JSON с полем modules — ровно три объекта с полями file, responsibility, public_api, "
              "имена storage.py, crm.py, main.py; и поле rationale. Не пиши код. ТЗ:\n"+spec)
    plan=None
    for attempt in range(2):
        try:
            plan=json.loads(ask(ARCHITECT,planning,True))
            if sorted(x["file"] for x in plan["modules"])!=sorted(NAMES):
                raise ValueError("Unknown modules")
            for entry in plan["modules"]:
                public_api=entry.get("public_api")
                if isinstance(public_api,(list,dict)):
                    entry["public_api"]=json.dumps(public_api,ensure_ascii=False)
                elif not isinstance(public_api,str) or not public_api.strip():
                    raise ValueError("Missing planned interfaces")
                if not isinstance(entry.get("responsibility"),str) or not entry["responsibility"].strip():
                    raise ValueError("Missing module responsibility")
            break
        except Exception as err:
            if attempt:raise
            planning+="\nИсправь структуру JSON и используй только эти три имени файлов."
    print("ARCHITECTURE:",json.dumps(plan,ensure_ascii=False)[:1900],flush=True)
    written={}
    def prompt(name,feedback=""):
        other="\n".join("Уже создан "+k+":\n"+v[:6500] for k,v in written.items() if k!=name)
        contracts={
          "storage.py":("Реализуй только функции верхнего уровня load_records(path)->list и "
                        "save_records(path,records)->None. Сохраняй UTF-8 JSON в указанном файле. "
                        "Если файла нет, load_records возвращает []. Никаких классов и сетевых вызовов."),
          "crm.py":("Реализуй класс CRM(path), импортирующий созданный модуль storage. "
                    "В конструкторе загрузка через storage.load_records(path), после каждого изменения "
                    "сохранение через storage.save_records(path,records). "
                    "Публичные методы add(name,phone,note='')->dict, all()->list, "
                    "search(query)->list, edit(id,name=None,phone=None,note=None), "
                    "set_status(id,status). Возвращай словари заявок с id:int, name,phone,note,status. "
                    "Используй уникальный id при повторном открытии базы. "
                    "Не меняй другие записи при редактировании; ищи без учёта регистра."),
          "main.py":("Создай командный интерфейс с argparse и импортом CRM из crm. "
                     "Должны работать --db PATH и подкоманды add,list,search,edit,status. "
                     "Запуск --help должен успешно завершаться. "
                     "Ввод и вывод только для вымышленных заявок, без сети.")
        }
        return ("Напиши ПОЛНЫЙ исходный код файла "+name+" на Python по ТЗ. "
                "Верни только Python без пояснений и без разметки. "
                "Контракт именно этого файла: "+contracts[name]+
                " ТЗ:\n"+spec+"\nПлан архитектора:\n"+
                json.dumps(plan,ensure_ascii=False)[:3400]+
                "\nУже готовые взаимосвязанные модули:\n"+other+
                ("\nОшибка предыдущей попытки. Исправь именно свой файл:\n"+feedback[-3500:] if feedback else ""))
    for filename in NAMES:
        feedback=""
        for attempt in range(2):
            try:
                txt=source(ask(WRITER,prompt(filename,feedback)))
                store(filename,txt);written[filename]=txt
                print("WRITER_FILE:",filename,"size",len(txt),"try",attempt+1,flush=True)
                break
            except Exception as error:
                feedback=type(error).__name__+": "+str(error)
                print("WRITER_RETRY:",filename,feedback[:300],flush=True)
                if attempt:raise
    ok,log=tests()
    for fix in range(3):
        if ok:break
        print("TEST_REPAIR:",fix+1,log[-1200:],flush=True)
        filename=("storage.py" if "storage.py" in log else
                  "main.py" if "test_20" in log else "crm.py")
        txt=source(ask(WRITER,prompt(filename,log)))
        store(filename,txt);written[filename]=txt
        ok,log=tests()
    if not ok:
        print("FINAL_TEST_FAILURE:",log[-5000:],flush=True)
        raise ValueError("Independent acceptance tests did not pass within retry limit")
    print("ACCEPTANCE_SUCCEEDED:",log[-1100:],flush=True)
    reviewer_prompt=("Ты независимый ревизор. Проверь русский ТЗ мини-CRM: добавление заявок, изменение "
        "статусов, поиск без учёта регистра, редактирование, сохранение в JSON, CLI. "
        "Ответь строго одним JSON-объектом с ключом verdict: REVIEW_OK, если реализация соответствует, "
        "или REVIEW_BAD, если нет; и необязательным ключом reason. "
        "ТЗ:\n"+spec+"\nИсходные файлы:\n"+
        "\n".join(name+":\n"+(DIR/name).read_text(encoding="utf-8")[:8000] for name in NAMES)+
        "\nПроверки:\n"+log[-900:])
    try:review=json.loads(ask(REVIEWER,reviewer_prompt,True))
    except ValueError:review={}
    print("SECOND_AGENT:",json.dumps(review,ensure_ascii=False)[:1100],flush=True)
    if review.get("verdict")!="REVIEW_OK":raise ValueError("Independent reviewer did not approve")
    proof={"status":"two_models_reviewed","architecture_model":ARCHITECT,"writer":WRITER,
           "reviewer":REVIEWER,"review_verdict":review["verdict"],"tests_passed":20,
           "source_modules":list(NAMES),"model_calls":CALLS,
           "duration_seconds":round(time.monotonic()-started,1),
           "sha256":{n:hashlib.sha256((DIR/n).read_bytes()).hexdigest() for n in NAMES}}
    (DIR/"architecture-plan.json").write_text(json.dumps(plan,ensure_ascii=False,indent=2),encoding="utf-8")
    (DIR/"verification-manifest.json").write_text(json.dumps(proof,ensure_ascii=False,indent=2),encoding="utf-8")
    print("CRM_TWO_AGENT_SUCCESS:",json.dumps(proof,ensure_ascii=False),flush=True)
if __name__=="__main__":
    try:run()
    except Exception as error:
        print("CRM_PILOT_SAFE_STOP:",type(error).__name__,str(error)[:550],flush=True)
        raise SystemExit(1)
